1	//! Command line helpers.
2	//!
3	//! `test4.cpp` reads its single optional argument with `std::atoi`, which has
4	//! semantics no `std` Rust parser reproduces: leading whitespace is skipped, an
5	//! optional sign is accepted, parsing stops at the first non-digit, a string
6	//! with no digits at all yields `0`, and out-of-range values are truncated to
7	//! `int` rather than reported as an error.
8	
9	/// Reimplementation of C's `atoi` as glibc provides it: `(int) strtol(s, NULL, 10)`.
10	///
11	/// `strtol` saturates at `LONG_MIN` / `LONG_MAX` (64-bit on this platform) and
12	/// the result is then truncated to 32 bits, so e.g. `"99999999999999999999"`
13	/// becomes `-1` just as it does in C.
14	pub fn atoi(s: &str) -> i32 {
15	    let bytes = s.as_bytes();
16	    let mut i = 0usize;
17	
18	    // isspace(): space, \t, \n, \v, \f, \r
19	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
20	        i += 1;
21	    }
22	
23	    let mut negative = false;
24	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
25	        negative = bytes[i] == b'-';
26	        i += 1;
27	    }
28	
29	    // Accumulate in i64 (== C `long` here) with saturation, mirroring strtol.
30	    let mut acc: i64 = 0;
31	    let mut saturated = false;
32	    while i < bytes.len() && bytes[i].is_ascii_digit() {
33	        let digit = i64::from(bytes[i] - b'0');
34	        if !saturated {
35	            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
36	                Some(v) => acc = v,
37	                None => saturated = true,
38	            }
39	        }
40	        i += 1;
41	    }
42	
43	    let value = if saturated {
44	        if negative {
45	            i64::MIN
46	        } else {
47	            i64::MAX
48	        }
49	    } else if negative {
50	        -acc
51	    } else {
52	        acc
53	    };
54	
55	    value as i32
56	}
