[package]
name = "earcut_test4"
version = "0.1.0"
edition = "2021"
description = "Pure-Rust port of the mapbox earcut polygon triangulation used by tests/test4.cpp"
publish = false

# Library code lives in src/ and is organised into modules.
[lib]
name = "earcut_test4"
path = "src/lib.rs"

# The entry test file sits in the package root, exactly like test4.cpp did.
[[bin]]
name = "test4"
path = "test4.rs"

[dependencies]
# Zero external dependencies: std only.

[profile.release]
opt-level = 3
overflow-checks = false
//! Pure-Rust, dependency-free port of the pieces of the C++ program
//! `tests/test4.cpp` that lived outside `main`: the `mapbox::earcut`
//! polygon triangulation, the polygon the test builds, and the C `atoi`
//! argument parsing.
//!
//! ```
//! use earcut_test4::{earcut::earcut, polygon::overlapping_squares};
//!
//! let indices = earcut(&overlapping_squares(1));
//! assert_eq!(indices, vec![2, 3, 0, 0, 1, 2]);
//! ```

pub mod cli;
pub mod earcut;
pub mod polygon;

/// Render a triangle index list the way `test4.cpp` does: every index followed
/// by a single space, with no trailing newline.
pub fn format_indices(indices: &[u32]) -> String {
    let mut out = String::new();
    for idx in indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    out
}
